        g.fillRect(cx - R3, cy - R3, 2 * R3, 2 * R3);
        const sw = 2 * R3 / Z;
        g.drawImage(o.frame, p.x / k0 - sw / (2 * k0), p.y / k0 - sw / (2 * k0), sw / k0, sw / k0, cx - R3, cy - R3, 2 * R3, 2 * R3);
        g.restore();
        g.strokeStyle = "rgba(90,255,176,.95)";
        g.lineWidth = 2 * px;
        g.beginPath();
        g.arc(cx, cy, R3, 0, 7);
        g.stroke();
        g.strokeStyle = "rgba(255,255,255,.9)";
        g.lineWidth = 1.5 * px;
        g.beginPath();
        g.moveTo(cx - 14 * px, cy);
        g.lineTo(cx + 14 * px, cy);
        g.moveTo(cx, cy - 14 * px);
        g.lineTo(cx, cy + 14 * px);
        g.stroke();
        g.fillStyle = "#fff";
        g.font = `700 ${12 * px}px system-ui`;
        g.textBaseline = "alphabetic";
        g.fillText(drag2.kind === "handle" ? NAMES[drag2.i] : dragA.name, cx, cy - R3 - 6 * px);
